import { isProtocolEvent } from '~/_engine/compile/utils.ts';
import type { Primitive } from '~/primitive.ts';

/** The primitive type tag for the deduplication feature. */
export interface DedupPrimitive extends Primitive<'dedup'> {}

/** Unique symbol used to enforce one dedup registration per handler scope. */
const DEDUP_KEY = Symbol('dedup');

/**
 * Creates the deduplication primitive. When registered, this primitive
 * intercepts every outgoing message and stamps it with a unique `_messageId`
 * string generated by the engine.
 *
 * Clients store the IDs of messages they have already processed and discard any
 * incoming message whose `_messageId` they have seen before. This protects
 * against duplicate deliveries that can occur when a replay, retry, or network
 * hiccup causes the same message to arrive more than once.
 *
 * Internal protocol events (events whose names start with `_`) are not stamped.
 *
 * @example
 * ```ts
 * import '@wskit/server/dedup';
 *
 * server('chat').dedup(); // outgoing messages get { ..., _messageId: 'msg_…' }
 * ```
 */
export function dedup(): DedupPrimitive {
  return {
    __wskit: 'dedup',
    __kind: 'infrastructure',
    __identity: [DEDUP_KEY],
    __dependencies: [],
    __requires: {},
    __setup(engine) {
      engine.installOnce(DEDUP_KEY, () => {
        engine.onOutgoing((message) => {
          // Skip internal protocol events (e.g. `_ack`, `_replay`).
          if (isProtocolEvent(message.event)) return;

          return {
            event: message.event,
            payload: {
              ...(message.payload as Record<string, unknown>),
              _messageId: engine.generateId('msg'),
            },
          };
        });
      });
    },
  };
}

/**
 * Symbol key used to reference this primitive in dependency declarations.
 */
dedup.__key = DEDUP_KEY;
